      final maxTime = loop.intFlag(r'--max-time');
      expect(
        maxTime,
        isNotNull,
        reason: 'curl must pin --max-time explicitly (per-attempt cap)',
      );
      expect(
        loop.intFlag(r'--retry'),
        isNull,
        reason:
