  final String curl;
  final String header;
  final String body;
  final int attempts;
  final int sleepSeconds;

  static DownloadLoop parse(String runText) {
    final lines = runText.split('\n');
    final headerIndex = lines.indexWhere(
      (l) => RegExp(r'^\s*for\s+\w+\s+in\s+').hasMatch(l),
    );
