      .whereType<YamlMap>()
      .where((s) => s['name'] == stepName)
      .toList(growable: false);
  expect(
    hits,
    hasLength(1),
    reason:
        '$workflowPath must keep exactly one '
        '"$stepName" step — the lint below guards that step',
  );
  return hits.single;
