    final sleep = bodyLines
        .map(RegExp(r'^\s*sleep\s+(\d+)').firstMatch)
        .whereType<RegExpMatch>()
        .map((m) => int.parse(m.group(1)!))
        .toList(growable: false);
    return DownloadLoop(
      header: header,
      body: bodyLines.join('\n'),
      attempts: attempts,
      curl: curl,
      sleepSeconds: sleep.isEmpty ? 0 : sleep.first,
    );
