      (l) => RegExp(r'^\s*(if\s+)?curl\s').hasMatch(l),
    );
    if (curlStart < 0) fail('no curl invocation inside the download loop');
    final cmd = <String>[bodyLines[curlStart]];
    var j = curlStart;
    while (cmd.last.trimRight().endsWith(r'\') && j < bodyLines.length - 1) {
      j++;
      cmd.add(bodyLines[j]);
    }
