      // covering the tail.
      final worstCaseSeconds =
          loop.attempts * maxTime! + (loop.attempts - 1) * loop.sleepSeconds;
      const reserveSeconds = 60; // one connect timeout + unzip + slack
      final budgetSeconds = timeoutMinutes! * 60;
