#!/usr/bin/env bash
set -euo pipefail
cd /tmp/gh1759/sim
REPO=/home/runner/work/flutter_agent_harness/flutter_agent_harness
W=$REPO/.github/workflows/build-macos.yml
SH=$(head -1 blob.meta)
SZ=$(tail -1 blob.meta)
PORT=18721

extract() {
  local src=$1 out=$2
  local start end
  start=$(grep -n 'name: Restore vendored WasmRun macOS framework' "$src" | cut -d: -f1)
  end=$(awk -v s=$start 'NR>s && /ls -la "\$DEST\/WasmRun.xcframework"/{print NR; exit}' "$src")
  sed -n "$((start+3)),$end p" "$src" | sed 's/^          //' > "$out"
}

git -C "$REPO" show '4820a89^:.github/workflows/build-macos.yml' > /tmp/gh1759/sim/wf_old.yml
extract "$W" step_new.raw
extract /tmp/gh1759/sim/wf_old.yml step_old.raw

SUB='s#^LOCAL_SRC=.*#LOCAL_SRC="/tmp/gh1759/sim/no-such-local"#;
s#^DEST=.*#DEST="$SIM_DEST"#;
s#^ZIP=.*#ZIP="$SIM_ZIP"#;
s#^ASSET_DIGEST=.*#ASSET_DIGEST="'"$SH"'"#;
s#^ASSET_BYTES=.*#ASSET_BYTES='"$SZ"'#;
s#--max-time 240#--max-time 3#;
s#shasum -a 256 -c -#sha256sum -c -#g;
s#https://github.com/juancastillo0/wasm_run/releases/download/wasm_run-v0.1.0/WasmRun.xcframework.zip#http://127.0.0.1:'"$PORT"'/blob.zip#'

sed "$SUB" step_new.raw > step_sim.sh
sed "$SUB" step_old.raw > step_old_sim.sh
bash -n step_sim.sh
bash -n step_old_sim.sh
echo "SYNTAX-OK (new=$(wc -l < step_sim.sh) lines, old=$(wc -l < step_old_sim.sh) lines)"
grep -n 'SIM_ZIP' step_sim.sh step_old_sim.sh
echo "run: leakage check (must be 0 0): $(grep -c '^run:' step_sim.sh) $(grep -c '^run:' step_old_sim.sh)"

